        internal async Task Exercise()
        {
            stage("真实物理结构和原候选");Assert.Equal(model.TargetMode,await Scalar(session,"SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='global_source' AND COLUMN_NAME='global_target_name'"));
            middle=(await Post(owner,Middle+"add",new{globalTargetId=Id(First),status=1})).GetProperty("id").GetString()!;other=(await Post(owner,Middle+"add",new{globalTargetId=Id(First+1),status=1})).GetProperty("id").GetString()!;destinations.Add(middle,First);destinations.Add(other,First+1);multi=[other,middle];checkedIds=[middle,other];await MiddleStorage();
            var options=await Post(client,Source+"findNameIdSelectedGlobalSource38",new{});Assert.Equal(2,options.GetArrayLength());Assert.Contains(options.EnumerateArray(),row=>row.GetProperty("id").GetString()==middle&&row.GetProperty("text").GetString()==labels[First]);
            var selected=await Post(client,Middle+"selection/selected",new{selectedIds=multi});Assert.Equal(multi,selected.EnumerateArray().Select(row=>row.GetProperty("id").GetString()));
            var bytes=Encoding.UTF8.GetBytes("全局数组正式附件");var file=await Upload(bytes);var added=await Post(client,Source+"add",new{name="正式数组消费",globalSourceIds=multi,selectedGlobalSourceIds=checkedIds,attachments=new[]{file}});RecordId=added.GetProperty("id").GetString()!;Check(added);await Storage();await References(file,1);await Download(file,bytes);
            var foreign=Row("id",ForeignId,"yz_project_id",101L,"name","其它项目不变","global_source_ids",JsonSerializer.Serialize(multi),"selected_global_source_ids",JsonSerializer.Serialize(checkedIds));if(model.SourceMode==1){foreign["global_source_global_target_names"]="[\"其它项目历史\"]";foreign["selected_global_source_global_target_names"]="[\"其它项目历史\"]";}await store.InsertAsync("cached_consumer",foreign);var foreignBefore=JsonSerializer.Serialize(await Physical("cached_consumer",Id(ForeignId)));
