            await store.UpdateAsync("global_target",First+1,Row("delete_no",null));labels[First+1]="恢复乙名称";await Post(owner,Target+"update",new{id=Id(First+1),name=labels[First+1]});Check(await Detail());destinations[middle]=First;await Post(owner,Middle+"update",new{id=middle,globalTargetId=Id(First)});checkedIds=[middle,other];Check(await Post(client,Source+"update",new{id=RecordId,selectedGlobalSourceIds=checkedIds}));await Storage();
            stage("原维护列表及按ID回填");var expected=new List<string>{"2"};if(model.TargetMode==1)expected.Add("1");if(model.SourceMode==1)expected.Add("3");var tables=await Post(owner,"/api/admin/sys/system_maintenance/tables",new{});Assert.Equal(expected.Order(StringComparer.Ordinal),tables.EnumerateArray().Select(row=>row.GetProperty("id").GetString()!).Order(StringComparer.Ordinal));
            if(model.TargetMode==0)await FreshWebHttp.SendAsync(owner,HttpMethod.Post,"/api/admin/sys/system_maintenance/backfill_join_columns",new{configTableId="1"},HttpStatusCode.BadRequest);else{await store.UpdateAsync("global_source",long.Parse(middle,CultureInfo.InvariantCulture),Row("global_target_name","故意旧中间名"));Assert.True((await Backfill("1")).GetProperty("affectedRows").GetInt32()>0);Check(await Detail());Assert.Equal(0,(await Backfill("1")).GetProperty("affectedRows").GetInt32());}
            if(model.SourceMode==1){await store.UpdateAsync("cached_consumer",long.Parse(RecordId,CultureInfo.InvariantCulture),Row("global_source_global_target_names","[\"故意旧名\"]","selected_global_source_global_target_names","[\"故意旧名\"]"));Assert.True((await Backfill("3")).GetProperty("affectedRows").GetInt32()>0);Check(await Detail());await Storage();Assert.Equal(0,(await Backfill("3")).GetProperty("affectedRows").GetInt32());}else await FreshWebHttp.SendAsync(owner,HttpMethod.Post,"/api/admin/sys/system_maintenance/backfill_join_columns",new{configTableId="3"},HttpStatusCode.BadRequest);
            stage("原两种Excel数组合同和整批失败");await Post(client,Source+"importDatas30",new{requestJson=new[]{Import("原数组导入")}});var before=await Snapshot();await FreshWebHttp.SendAsync(client,HttpMethod.Post,Source+"importDatas30",new{requestJson=new[]{Import("批首行"),Import("批尾失败",true)}},HttpStatusCode.BadRequest);Assert.Equal(before,await Snapshot());
            // 沿原V8导出合同：R1两种数组控件输出原ID，R0输出派生名称；导入的名称合同另行核验。
            var ticket=(await Post(client,Source+"initExport",new PageRequest{SelectedIds=[RecordId]})).GetString()!;using(var response=await client.GetAsync(ExportDownloadAccess.DownloadPath+"?exportId="+Uri.EscapeDataString(ticket))){Assert.Equal(HttpStatusCode.OK,response.StatusCode);using var book=new XLWorkbook(new MemoryStream(await response.Content.ReadAsByteArrayAsync()));var sheet=book.Worksheet(1);var headers=sheet.Row(1).CellsUsed().ToDictionary(cell=>cell.GetString(),cell=>cell.Address.ColumnNumber);Assert.Equal(model.SourceMode==1?multi:Expected(multi),JsonSerializer.Deserialize<string?[]>(sheet.Row(2).Cell(headers["原下拉"]).GetString()));if(model.SourceMode==1)Assert.Equal(checkedIds,JsonSerializer.Deserialize<string[]>(sheet.Row(2).Cell(headers["原单选"]).GetString()));else Assert.Equal(Expected(checkedIds),JsonSerializer.Deserialize<string?[]>(sheet.Row(2).Cell(headers["原单选"]).GetString()));}
            if(model.SourceMode==1)await LateBatches();
            stage("复制和晚期文件整笔回滚");var copy=(await Post(client,Source+"copy/"+RecordId,new{})).GetProperty("id").GetString()!;await References(file,2);var next=await Upload(Encoding.UTF8.GetBytes("晚期失败数组附件"));await Sql("ALTER TABLE `yz_file_ref` ADD CONSTRAINT `mt_array_file` CHECK (`file_id` <> "+long.Parse(next,CultureInfo.InvariantCulture).ToString(CultureInfo.InvariantCulture)+")");try{before=await Snapshot();await FreshWebHttp.SendAsync(client,HttpMethod.Post,Source+"update",new{id=RecordId,name="不应提交",globalSourceIds=new[]{middle},selectedGlobalSourceIds=new[]{other},attachments=new[]{next}},HttpStatusCode.InternalServerError);Assert.Equal(before,await Snapshot());}finally{await Sql("ALTER TABLE `yz_file_ref` DROP CHECK `mt_array_file`");}Check(await Detail());await References(file,2);await ForeignUnchanged();
            stage("原type=2继承和复选来源动作");await Grant("10","[]");await Post(client,Middle+"selection/selected",new{selectedIds=multi});await Post(client,Source+"findNameIdSelectedGlobalSource38",new{});await Grant("30","[\"is_update\",\"is_export\"]");await FreshWebHttp.SendAsync(client,HttpMethod.Post,Middle+"selection/selected",new{selectedIds=multi},HttpStatusCode.Forbidden);before=await Snapshot();await FreshWebHttp.SendAsync(client,HttpMethod.Post,Source+"update",new{id=RecordId,globalSourceIds=multi},HttpStatusCode.Forbidden);Assert.Equal(before,await Snapshot());Check(await Post(client,Source+"update",new{id=RecordId,selectedGlobalSourceIds=checkedIds}));await Post(client,Source+"findNameIdSelectedGlobalSource38",new{});await Download(file,bytes,HttpStatusCode.Unauthorized);await Grant("30","[\"is_all\"]");await Post(client,Source+"importDatas30",new{requestJson=new[]{Import("无独立目标查询导入")}});await Grant("10","[\"is_all\"]");
            stage("省略、显式null及历史缺失位置");Check(await Post(client,Source+"update",new{id=RecordId,name="只改名称"}));var saved=multi;multi=[];Check(await Post(client,Source+"update",new{id=RecordId,globalSourceIds=(string[]?)null}));Assert.Null((await Physical("cached_consumer",RecordId))["global_source_ids"]);multi=saved;Check(await Post(client,Source+"update",new{id=RecordId,globalSourceIds=multi}));
            var missing=Id(ForeignId+15000);multi=[other,missing,middle];await store.UpdateAsync("cached_consumer",long.Parse(RecordId,CultureInfo.InvariantCulture),Row("global_source_ids",JsonSerializer.Serialize(multi)));if(model.SourceMode==1)await Backfill("3");var history=await Detail();Assert.Equal(new[]{labels[First+1],null,labels[First]},Array(history,"globalSourceGlobalTargetNames"));before=await Snapshot();await FreshWebHttp.SendAsync(client,HttpMethod.Post,Source+"update",new{id=RecordId,globalSourceIds=multi},HttpStatusCode.InternalServerError);Assert.Equal(before,await Snapshot());multi=saved;Check(await Post(client,Source+"update",new{id=RecordId,globalSourceIds=multi}));
            if(model.TargetMode==0&&model.SourceMode==1&&model.InnerType=="string")await LargeCheckbox();
            await FreshWebHttp.SendAsync(client,HttpMethod.Delete,Source,new{id=copy});await References(file,1);await Grant("30","[]");await FreshWebHttp.SendAsync(client,HttpMethod.Post,Source+"page",new{},HttpStatusCode.Forbidden);await FreshWebHttp.SendAsync(client,HttpMethod.Post,Source+"findNameIdSelectedGlobalSource38",new{},HttpStatusCode.Forbidden);await Grant("30","[\"is_all\"]");await Storage();await ForeignUnchanged();
            /// <summary>外项目物理样本保持；不把此断言扩称完整跨后台读取ACL矩阵。</summary>
            async Task ForeignUnchanged()=>Assert.Equal(foreignBefore,JsonSerializer.Serialize(await Physical("cached_consumer",Id(ForeignId))));
        }
        /// <summary>130消费者跨过128批界，最后一条约束拒绝时必须还原上游、已处理批次和全部文件表。</summary>
        private async Task LateBatches()
        {
            stage("130消费者名称传播与末批回滚");for(var index=0;index<130;index++)await store.InsertAsync("cached_consumer",Row("id",ForeignId+2000+index,"yz_project_id",100L,"name",index==129?"跨批阻断":"跨批样本"+index,"global_source_ids",JsonSerializer.Serialize(new[]{middle}),"selected_global_source_ids",JsonSerializer.Serialize(new[]{middle}),"global_source_global_target_names",JsonSerializer.Serialize(new[]{labels[First]}),"selected_global_source_global_target_names",JsonSerializer.Serialize(new[]{labels[First]})));
            labels[First]="跨批改名";await Post(owner,Target+"update",new{id=Id(First),name=labels[First]});await BatchNames(labels[First]!);Check(await Detail());const string blocked="不应提交改名";await Sql("ALTER TABLE `cached_consumer` ADD CONSTRAINT `mt_array_name` CHECK (`name` <> '跨批阻断' OR JSON_UNQUOTE(JSON_EXTRACT(`global_source_global_target_names`,'$[0]')) <> '"+blocked+"')");try{var before=await Snapshot();await FreshWebHttp.SendAsync(owner,HttpMethod.Post,Target+"update",new{id=Id(First),name=blocked},HttpStatusCode.InternalServerError);Assert.Equal(before,await Snapshot());}finally{await Sql("ALTER TABLE `cached_consumer` DROP CHECK `mt_array_name`");}
            stage("130消费者原维护与末批回滚");for(var index=0;index<130;index++)await store.UpdateAsync("cached_consumer",ForeignId+2000+index,Row("global_source_global_target_names","[\"故意旧名\"]","selected_global_source_global_target_names","[\"故意旧名\"]"));await Sql("ALTER TABLE `cached_consumer` ADD CONSTRAINT `mt_array_fill` CHECK (`name` <> '跨批阻断' OR JSON_UNQUOTE(JSON_EXTRACT(`global_source_global_target_names`,'$[0]')) <> '跨批改名')");try{var before=await Snapshot();await FreshWebHttp.SendAsync(owner,HttpMethod.Post,"/api/admin/sys/system_maintenance/backfill_join_columns",new{configTableId="3"},HttpStatusCode.InternalServerError);Assert.Equal(before,await Snapshot());}finally{await Sql("ALTER TABLE `cached_consumer` DROP CHECK `mt_array_fill`");}var beforeFill=await store.ReadIncludingDeletedAsync("cached_consumer");var filled=await Backfill("3");var afterFill=await store.ReadIncludingDeletedAsync("cached_consumer");MaintenanceDelta=NativeArrayMaintenanceAudit.Verify(beforeFill,afterFill,Enumerable.Range(0,130).Select(index=>ForeignId+2000+index).ToHashSet(),"100",filled.GetProperty("affectedRows").GetInt32());Assert.Equal(0,(await Backfill("3")).GetProperty("affectedRows").GetInt32());await BatchNames(labels[First]!);
        }
        /// <summary>只在一个正式模型验证5000完整候选／写入与第5001项拒绝；合成行最终随独占库清理。</summary>
        private async Task LargeCheckbox()
        {
            stage("真实5000复选及第5001项拒绝");var ids=Enumerable.Range(0,5000).Select(index=>Id(ForeignId+100000+index)).ToArray();await store.UpdateAsync("global_source",long.Parse(middle,CultureInfo.InvariantCulture),Row("status",0));await store.UpdateAsync("global_source",long.Parse(other,CultureInfo.InvariantCulture),Row("status",0));await session.InTransactionAsync(async()=>{foreach(var id in ids)await store.InsertAsync("global_source",Row("id",long.Parse(id,CultureInfo.InvariantCulture),"global_target_id",Id(First),"status",1));return true;});
            var choices=await Post(client,Source+"findNameIdSelectedGlobalSource38",new{});Assert.Equal(5000,choices.GetArrayLength());var large=await Post(client,Source+"update",new{id=RecordId,globalSourceIds=(string[]?)null,selectedGlobalSourceIds=ids});Assert.Equal(ids,Array(large,"selectedGlobalSourceIds"));Assert.Equal(5000,large.GetProperty("selectedGlobalSourceGlobalTargetNames").GetArrayLength());await store.InsertAsync("global_source",Row("id",ForeignId+105000,"global_target_id",Id(First),"status",1));await FreshWebHttp.SendAsync(client,HttpMethod.Post,Source+"findNameIdSelectedGlobalSource38",new{},HttpStatusCode.InternalServerError);var selected=await Post(client,Source+"findNameIdSelectedGlobalSource38",new{id=new[]{ids[^1]}});Assert.Equal(ids[^1],Assert.Single(selected.EnumerateArray()).GetProperty("id").GetString());
            await Sql("UPDATE `global_source` SET `status`=0 WHERE `id` BETWEEN "+Id(ForeignId+100000)+" AND "+Id(ForeignId+105000));await store.UpdateAsync("global_source",long.Parse(middle,CultureInfo.InvariantCulture),Row("status",1));await store.UpdateAsync("global_source",long.Parse(other,CultureInfo.InvariantCulture),Row("status",1));Check(await Post(client,Source+"update",new{id=RecordId,globalSourceIds=multi,selectedGlobalSourceIds=checkedIds}));
        }
        /// <summary>所有正式跨批样本的两份物理名称数组均逐行核对。</summary>
        private async Task BatchNames(string expected){var rows=(await store.ReadIncludingDeletedAsync("cached_consumer")).Where(row=>SqlRowStore.Id(row)>=ForeignId+2000&&SqlRowStore.Id(row)<ForeignId+2130).ToArray();Assert.Equal(130,rows.Length);Assert.All(rows,row=>{Assert.Equal(new[]{expected},JsonSerializer.Deserialize<string[]>(SqlRowStore.Text(row,"global_source_global_target_names")));Assert.Equal(new[]{expected},JsonSerializer.Deserialize<string[]>(SqlRowStore.Text(row,"selected_global_source_global_target_names")));});}
        /// <summary>按实际元数据类型和生产者模式核对物理中间行。</summary>
        private async Task MiddleStorage(){var row=await Physical("global_source",middle);Assert.Equal(Id(destinations[middle]),SqlRowStore.Text(row,"global_target_id"));if(model.InnerType=="string")Assert.IsType<string>(row["global_target_id"]);else Assert.IsType<long>(row["global_target_id"]);if(model.TargetMode==0)Assert.False(row.ContainsKey("global_target_name"));else Assert.Equal(labels[destinations[middle]],row["global_target_name"]);}
        /// <summary>数组作为数组比较，长ID不经浮点；省略与null都通过实际HTTP处理。</summary>
        private void Check(JsonElement row){Assert.Equal(multi,Array(row,"globalSourceIds"));Assert.Equal(checkedIds,Array(row,"selectedGlobalSourceIds"));Assert.Equal(Expected(multi),Array(row,"globalSourceGlobalTargetNames"));Assert.Equal(Expected(checkedIds),Array(row,"selectedGlobalSourceGlobalTargetNames"));}
        /// <summary>非冗余实体不应存在名称列，冗余实体名称与原ID数组保持同一顺序。</summary>
        private async Task Storage(){var row=await Physical("cached_consumer",RecordId);Assert.Equal("100",SqlRowStore.Text(row,"yz_project_id"));Assert.Equal(multi,JsonSerializer.Deserialize<string[]>(SqlRowStore.Text(row,"global_source_ids")));Assert.Equal(checkedIds,JsonSerializer.Deserialize<string[]>(SqlRowStore.Text(row,"selected_global_source_ids")));foreach(var (field,ids) in new[]{("global_source_global_target_names",multi),("selected_global_source_global_target_names",checkedIds)}){if(model.SourceMode==0)Assert.False(row.ContainsKey(field));else Assert.Equal(Expected(ids),JsonSerializer.Deserialize<string?[]>(SqlRowStore.Text(row,field)));}}
        /// <summary>名称只由已核关系角色推导，不能按数组位置猜目标或覆盖另一控件。</summary>
        private string?[] Expected(IEnumerable<string> ids)=>ids.Select(id=>labels[destinations[id]]).ToArray();
        /// <summary>原JSON数组和显式空值统一仅供断言，不能改变实际请求或响应。</summary>
        private static string?[] Array(JsonElement row,string field)=>row.GetProperty(field).ValueKind==JsonValueKind.Null?[]:row.GetProperty(field).EnumerateArray().Select(value=>value.ValueKind==JsonValueKind.Null?null:value.GetString()).ToArray();
        /// <summary>原复选R1用ID数组、R0用名称；多选始终用名称数组唯一反查。</summary>
        private Dictionary<string,object?> Import(string record,bool invalid=false)=>Row("名称",record,"原下拉",JsonSerializer.Serialize(invalid?new[]{"不存在"}:Expected(multi)),"原单选",JsonSerializer.Serialize(model.SourceMode==1?checkedIds:Expected(checkedIds)));
        /// <summary>快照覆盖全部业务与三文件表，包括墓碑，不只比较一条VO。</summary>
        private async Task<string> Snapshot(){var rows=new SortedDictionary<string,object>(StringComparer.Ordinal);foreach(var table in new[]{"global_target","global_source","cached_consumer"})rows[table]=(await store.ReadIncludingDeletedAsync(table)).OrderBy(row=>SqlRowStore.Id(row)).ToArray();foreach(var table in new[]{"yz_file_ref","yz_file_library","yz_file_library_folder"})rows[table]=(await files.ReadIncludingDeletedAsync(table)).OrderBy(row=>SqlRowStore.Id(row)).ToArray();return Convert.ToHexStringLower(SHA256.HashData(Encoding.UTF8.GetBytes(JsonSerializer.Serialize(rows))));}
        /// <summary>物理核验仅使用本轮已经pin的参数化存储。</summary>
        private async Task<IReadOnlyDictionary<string,object?>> Physical(string table,string id)=>Assert.Single(await store.ReadIncludingDeletedAsync(table,Row("id",long.Parse(id,CultureInfo.InvariantCulture))));
        /// <summary>实际HTTP统一检查原R合同。</summary>
        private static async Task<JsonElement> Post(HttpClient sender,string path,object value)=>(await FreshWebHttp.SendAsync(sender,HttpMethod.Post,path,value)).GetProperty("data");
        /// <summary>名称回显必须来自实际详情链，不能以直接SQL读取替代。</summary>
        private async Task<JsonElement> Detail()=>(await FreshWebHttp.SendAsync(client,HttpMethod.Get,Source+"detail/"+RecordId)).GetProperty("data");
        /// <summary>原维护按钮使用正式owner；普通业务写入仍来自普通账号。</summary>
        private Task<JsonElement> Backfill(string table)=>Post(owner,"/api/admin/sys/system_maintenance/backfill_join_columns",new{configTableId=table});
        /// <summary>撤权只影响本轮新库明确角色页面。</summary>
        private Task Grant(string page,string values)=>security.UpdateAsync("yz_role_permission",grants[page],Row("permission_values",values));
        /// <summary>保护文件沿真实上传计划、multipart与完成流程。</summary>
        private async Task<string> Upload(byte[] bytes){var id=(await Post(client,Files+"upload-plan",new{originalName="array-target.txt",mimeType="text/plain",sizeBytes=bytes.Length,configColumnId="39"})).GetProperty("fileId").GetString()!;using var content=new MultipartFormDataContent();content.Add(new ByteArrayContent(bytes),"file","array-target.txt");await FreshWebHttp.SendAsync(client,HttpMethod.Post,Files+"local-upload/"+id,content);await Post(client,Files+"complete",new{fileId=id});return id;}
        /// <summary>真实保护下载逐字比较，撤权保留原401。</summary>
        private async Task Download(string id,byte[] bytes,HttpStatusCode expected=HttpStatusCode.OK){using var response=await client.GetAsync(Files+"protected-content/"+id);Assert.Equal(expected,response.StatusCode);if(expected==HttpStatusCode.OK)Assert.Equal(bytes,await response.Content.ReadAsByteArrayAsync());}
        /// <summary>引用必须归属当前来源项目与原页。</summary>
        private async Task References(string id,int count){var rows=await files.ReadAsync("yz_file_ref",Row("file_id",long.Parse(id,CultureInfo.InvariantCulture)));Assert.Equal(count,rows.Count);Assert.All(rows,row=>{Assert.Equal("100",SqlRowStore.Text(row,"yz_project_id"));Assert.Equal("30",SqlRowStore.Text(row,"page_id"));});}
        /// <summary>固定约束和合成数据操作只进入已pin的新库，不接受外部SQL。</summary>
        private async Task Sql(string sql){await using var connection=new MySqlConnection(session.Options.ConnectionString);await connection.OpenAsync();await using var command=connection.CreateCommand();command.CommandText=sql;await command.ExecuteNonQueryAsync();}
    }
}
